<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { BookOpenCheck, Eye, Pencil, Plus, Trash2, X } from 'lucide-vue-next'
import { api } from '../api'
import { tr } from '../preferences'
import type { Device, ManagedGroup, ManagedUser, Strategy, StrategyEvaluation, StrategySettingDefinition } from '../types'

const records=ref<Strategy[]>([]),users=ref<ManagedUser[]>([]),devices=ref<Device[]>([]),groups=ref<ManagedGroup[]>([]),schema=ref<StrategySettingDefinition[]>([])
const loading=ref(true),open=ref(false),saving=ref(false),error=ref(''),editing=ref<Strategy>(),enabledKeys=ref<string[]>([])
const previewDevice=ref(''),preview=ref<StrategyEvaluation>(),previewing=ref(false)
const values=reactive<Record<string,boolean|string>>({})
const form=reactive({name:'',scope_type:'global',scope_id:'',priority:100,enabled:true})
const categories=computed(()=>[...new Set(schema.value.map(value=>value.category))])
const scopeOptions=computed(()=>{if(form.scope_type==='user')return users.value.map(value=>({id:value.id,name:value.display_name||value.username}));if(form.scope_type==='device')return devices.value.map(value=>({id:value.rustdesk_id,name:`${value.alias||value.hostname||value.rustdesk_id} · ${value.rustdesk_id}`}));if(form.scope_type==='user_group')return groups.value.filter(value=>value.kind==='user').map(value=>({id:value.id,name:value.name}));if(form.scope_type==='device_group')return groups.value.filter(value=>value.kind==='device').map(value=>({id:value.id,name:value.name}));return[]})
const scopeLabel=(strategy:Strategy)=>{if(strategy.scope_type==='global')return tr('Все устройства','All devices');if(strategy.scope_type==='user')return users.value.find(v=>v.id===strategy.scope_id)?.display_name||users.value.find(v=>v.id===strategy.scope_id)?.username||strategy.scope_id;if(strategy.scope_type==='device')return devices.value.find(v=>v.rustdesk_id===strategy.scope_id)?.alias||devices.value.find(v=>v.rustdesk_id===strategy.scope_id)?.hostname||strategy.scope_id;return groups.value.find(v=>v.id===strategy.scope_id)?.name||strategy.scope_id}
const settingCopies:Record<string,[string,string]>={require_login:['Требовать вход','Require login'],require_managed_device:['Только управляемые устройства','Managed devices only'],allow_remote_control:['Удалённое управление','Remote control'],allow_file_transfer:['Передача файлов','File transfer'],allow_clipboard:['Буфер обмена','Clipboard'],allow_tcp_tunnel:['TCP-туннель','TCP tunnel'],force_relay:['Принудительный relay','Force relay'],disable_direct_ip:['Отключить Direct IP','Disable Direct IP'],disable_lan_discovery:['Отключить LAN discovery','Disable LAN discovery'],disable_settings:['Заблокировать настройки клиента','Lock client settings'],id_server:['ID Server','ID Server'],relay_server:['Relay Server','Relay Server'],api_server:['API Server','API Server']}
const settingLabel=(key:string)=>settingCopies[key]?tr(...settingCopies[key]):schema.value.find(value=>value.key===key)?.label||key
async function load(){loading.value=true;error.value='';try{const [strategyValues,userValues,deviceValues,groupValues,definitions]=await Promise.all([api.strategies(),api.users(),api.devices(),api.groups(),api.strategySchema()]);records.value=strategyValues;users.value=userValues;devices.value=deviceValues;groups.value=groupValues;schema.value=definitions.map(value=>({...value,label:settingCopies[value.key]?tr(...settingCopies[value.key]):tr(value.label,value.label_en||value.label)}))}catch(reason){error.value=reason instanceof Error?reason.message:tr('Ошибка загрузки','Load failed')}finally{loading.value=false}}
function resetValues(){for(const key of Object.keys(values))delete values[key];for(const definition of schema.value)values[definition.key]=definition.kind==='boolean'?true:''}
function add(){editing.value=undefined;resetValues();enabledKeys.value=[];Object.assign(form,{name:'',scope_type:'global',scope_id:'',priority:100,enabled:true});open.value=true}
function edit(strategy:Strategy){editing.value=strategy;resetValues();enabledKeys.value=Object.keys(strategy.settings);for(const [key,value] of Object.entries(strategy.settings))values[key]=value as boolean|string;Object.assign(form,{name:strategy.name,scope_type:strategy.scope_type,scope_id:strategy.scope_id,priority:strategy.priority,enabled:strategy.enabled});open.value=true}
function changeScope(){form.scope_id=''}
function toggleSetting(key:string){enabledKeys.value=enabledKeys.value.includes(key)?enabledKeys.value.filter(value=>value!==key):[...enabledKeys.value,key]}
function payload(){const settings:Record<string,unknown>={};for(const key of enabledKeys.value)settings[key]=values[key];return{name:form.name,scope_type:form.scope_type,scope_id:form.scope_type==='global'?'':form.scope_id,priority:form.priority,settings,enabled:form.enabled}}
async function save(){if(!enabledKeys.value.length){error.value=tr('Выберите хотя бы один параметр','Select at least one setting');return}saving.value=true;error.value='';try{editing.value?await api.updateStrategy(editing.value.id,payload()):await api.createStrategy(payload());open.value=false;await load()}catch(reason){error.value=reason instanceof Error?reason.message:tr('Ошибка сохранения','Save failed')}finally{saving.value=false}}
async function toggle(strategy:Strategy){saving.value=true;try{await api.updateStrategy(strategy.id,{...strategy,enabled:!strategy.enabled});await load()}catch(reason){error.value=reason instanceof Error?reason.message:tr('Ошибка обновления','Update failed')}finally{saving.value=false}}
async function remove(strategy:Strategy){if(!confirm(tr(`Удалить стратегию «${strategy.name}»?`,`Delete strategy “${strategy.name}”?`)))return;saving.value=true;try{await api.deleteStrategy(strategy.id);await load()}catch(reason){error.value=reason instanceof Error?reason.message:tr('Ошибка удаления','Delete failed')}finally{saving.value=false}}
async function evaluate(){if(!previewDevice.value)return;previewing.value=true;error.value='';try{preview.value=await api.evaluateStrategy(previewDevice.value)}catch(reason){error.value=reason instanceof Error?reason.message:tr('Ошибка расчёта политики','Policy evaluation failed')}finally{previewing.value=false}}
onMounted(load)
</script>

<template>
  <section class="section-heading"><div><p class="eyebrow">Central policy</p><h2>{{tr('Стратегии','Strategies')}}</h2><p>{{tr('Наследуемые настройки автоматически доставляются официальным RustDesk Client через heartbeat.','Inherited settings are automatically delivered to the official RustDesk Client through heartbeat.')}}</p></div><button class="primary-button compact" @click="add"><Plus :size="17"/>{{tr('Добавить стратегию','Add strategy')}}</button></section>
  <p v-if="error" class="alert-error">{{error}}</p><p v-if="loading" class="panel empty-state">{{tr('Загрузка…','Loading…')}}</p>
  <section v-if="!loading" class="panel strategy-preview"><div><strong>{{tr('Итоговая политика устройства','Effective device policy')}}</strong><small>{{tr('Показывает результат наследования и реальные параметры RustDesk Client','Shows inheritance results and actual RustDesk Client settings')}}</small></div><select v-model="previewDevice"><option value="">{{tr('Выберите устройство','Select a device')}}</option><option v-for="device in devices" :key="device.rustdesk_id" :value="device.rustdesk_id">{{device.alias||device.hostname||device.rustdesk_id}} · {{device.rustdesk_id}}</option></select><button class="secondary-button" :disabled="!previewDevice||previewing" @click="evaluate"><Eye :size="15"/>{{tr('Рассчитать','Evaluate')}}</button><div v-if="preview" class="strategy-result"><span class="badge teal">{{preview.matched_strategy_ids.length}} {{tr('стратегий','strategies')}}</span><span v-for="(value,key) in preview.effective_settings" :key="key" class="badge neutral">{{settingLabel(String(key))}}: {{String(value)}}</span><p v-if="!Object.keys(preview.effective_settings).length">{{tr('Для устройства нет назначенных параметров.','No settings are assigned to this device.')}}</p></div></section>
  <section v-if="!loading" class="card-grid"><article v-for="strategy in records" :key="strategy.id" class="panel policy-card" :class="{inactive:!strategy.enabled}"><span class="metric-icon"><BookOpenCheck :size="20"/></span><div class="policy-content"><div><span class="badge" :class="strategy.enabled?'teal':'neutral'">{{strategy.enabled?tr('Доставляется','Delivered'):tr('Отключена','Disabled')}}</span><span class="badge neutral">{{tr('Приоритет','Priority')}} {{strategy.priority}}</span></div><h3>{{strategy.name}}</h3><p>{{scopeLabel(strategy)}} · {{strategy.scope_type}}</p><div><span v-for="(value,key) in strategy.settings" :key="key" class="badge neutral">{{settingLabel(String(key))}}: {{String(value)}}</span></div></div><div class="policy-actions"><button class="icon-btn" :title="tr('Редактировать','Edit')" @click="edit(strategy)"><Pencil :size="16"/></button><button class="text-button" @click="toggle(strategy)">{{strategy.enabled?tr('Выключить','Disable'):tr('Включить','Enable')}}</button><button class="icon-action" :title="tr('Удалить','Delete')" @click="remove(strategy)"><Trash2 :size="16"/></button></div></article><article v-if="!records.length" class="panel empty-state">{{tr('Стратегий пока нет.','No strategies yet.')}}</article></section>
  <div v-if="open" class="modal-backdrop" @click.self="open=false"><form class="modal-card strategy-editor" @submit.prevent="save"><div class="modal-heading"><h3>{{editing?tr('Редактирование стратегии','Edit strategy'):tr('Новая стратегия','New strategy')}}</h3><button type="button" class="icon-btn" @click="open=false"><X :size="20"/></button></div><label><span>{{tr('Название','Name')}}</span><input v-model="form.name" required minlength="2" maxlength="128"/></label><div class="form-grid"><label><span>{{tr('Область','Scope')}}</span><select v-model="form.scope_type" @change="changeScope"><option value="global">{{tr('Все устройства','All devices')}}</option><option value="user">{{tr('Пользователь','User')}}</option><option value="user_group">{{tr('Группа пользователей','User group')}}</option><option value="device">{{tr('Устройство','Device')}}</option><option value="device_group">{{tr('Группа устройств','Device group')}}</option></select></label><label v-if="form.scope_type!=='global'"><span>{{tr('Назначение','Assignment')}}</span><select v-model="form.scope_id" required><option value="" disabled>{{tr('Выберите…','Select…')}}</option><option v-for="value in scopeOptions" :key="value.id" :value="value.id">{{value.name}}</option></select></label><label><span>{{tr('Приоритет','Priority')}}</span><input v-model.number="form.priority" type="number" min="1" max="100000"/></label><label v-if="editing" class="check-label"><input v-model="form.enabled" type="checkbox"/><span>{{tr('Стратегия включена','Strategy enabled')}}</span></label></div><p class="membership-note">{{tr('Большее значение приоритета сильнее. При равном приоритете побеждает наиболее конкретное назначение.','A higher priority value wins. At equal priority, the most specific assignment wins.')}}</p><section v-for="category in categories" :key="category" class="strategy-category"><h4>{{category}}</h4><label v-for="definition in schema.filter(value=>value.category===category)" :key="definition.key" class="strategy-setting"><input type="checkbox" :checked="enabledKeys.includes(definition.key)" @change="toggleSetting(definition.key)"/><span><strong>{{definition.label}}</strong><small v-if="definition.server_only">{{tr('Проверяется на сервере','Enforced by server')}}</small></span><select v-if="definition.kind==='boolean'" v-model="values[definition.key]" :disabled="!enabledKeys.includes(definition.key)"><option :value="true">{{tr('Включено / разрешено','Enabled / allowed')}}</option><option :value="false">{{tr('Выключено / запрещено','Disabled / denied')}}</option></select><input v-else v-model="values[definition.key]" :disabled="!enabledKeys.includes(definition.key)" maxlength="2048" placeholder="server.example.com"/></label></section><div class="modal-actions"><button type="button" class="secondary-button" @click="open=false">{{tr('Отмена','Cancel')}}</button><button class="primary-button compact" :disabled="saving||!enabledKeys.length">{{saving?tr('Сохранение…','Saving…'):tr('Сохранить','Save')}}</button></div></form></div>
</template>
